"""Deterministic capacity/retention plot with construction safety explicitly scoped."""
import hashlib,json
from pathlib import Path
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parents[4];PUBLIC=ROOT/'results/research/loki/h3aq'
def main():
    path=PUBLIC/'summary.json';s=json.loads(path.read_text());assert s['status']=='validated';plt.rcParams.update({'font.size':10.5,'axes.spines.top':False,'axes.spines.right':False,'svg.fonttype':'none','svg.hashsalt':'cram-h3aq-public'});fig,axes=plt.subplots(1,2,figsize=(14,7.5));fig.subplots_adjust(left=.075,right=.97,bottom=.35,top=.75,wspace=.31);fig.suptitle('Safe 16-label construction still falls short of 95% capacity',x=.065,y=.95,ha='left',fontsize=17,fontweight='bold');fig.text(.065,.879,'FALSIFIED: only 2 / 8 D4-unfiltered banks pass · zero invalid states follow from the verified construction',fontsize=11.6,fontweight='bold');fig.text(.065,.819,'Same 16 raw N12 labels; D4 adds 128 attempted correlated views and an explicit invariance prior; no BP fits',fontsize=10.7)
    for index,r in enumerate(s['primary']):
        raw=next(x for x in s['rows']if x['index']==index and x['arm']=='raw_unfiltered');axes[0].bar(index-.17,raw['capacity_pct'],width=.32,color='#7f8c8d',label='Raw unfiltered'if index==0 else None);axes[0].bar(index+.17,r['capacity_pct'],width=.32,color='#287f77',label='D4 unfiltered'if index==0 else None);axes[0].annotate(f"{r['capacity_pct']:.1f}",(index+.17,r['capacity_pct']),xytext=(0,4),textcoords='offset points',ha='center',fontsize=8.5);axes[1].bar(index,r['true_state_retention_pct'],width=.6,color='#287f77');axes[1].annotate(f"{r['true_state_retention_pct']:.1f}",(index,r['true_state_retention_pct']),xytext=(0,4),textcoords='offset points',ha='center',fontsize=8.5)
    axes[0].axhline(95,color='#ae3f3a',ls='--',lw=1.3);axes[0].set_ylim(0,111);axes[0].set_ylabel('Exact valid-input capacity (%)');axes[0].set_title('A   D4 improves capacity, but six banks miss 95%',loc='left',fontweight='bold',pad=14);axes[0].legend(frameon=False,loc='upper center',bbox_to_anchor=(.5,-.12),ncol=2,fontsize=9)
    axes[1].set_ylim(0,100);axes[1].set_ylabel('True complete states retained by D4 support (%)');axes[1].set_title('B   Extra exclusions still reduce state diversity',loc='left',fontweight='bold',pad=14)
    for ax in axes:ax.set_xticks(range(8),['Z0','Z1','Z2','Z3','L0','L1','L2','L3']);ax.grid(axis='y',alpha=.17);ax.set_axisbelow(True)
    fig.text(.065,.255,'D4 supports retain 32–184 false exclusions. The published filtered baseline has 100% capacity but is unsafe.',fontsize=11,fontweight='bold');fig.text(.065,.19,'Safety is conditional on valid labels, actual D4 invariance, representable true leaper offsets and inherited queen lines.\nIt is verified before scoring, not treated as an independent empirical safety discovery. The capacity endpoint remains falsifiable.',fontsize=10.6,linespacing=1.5);fig.text(.065,.12,'All 24 outcomes and 18 complete supports retained; same seen finite N13 universe. No threshold tuning or bank replacement.\nH3ap’s pre-target JSON failure is preserved. H3aq changes receipt integer encoding only; computed source arrays remain identical.',fontsize=10.6,linespacing=1.5);fig.text(.065,.05,f"Charged preflight + run: {s['aggregate_CPU_seconds']:.3f} CPU s / {s['wall_seconds']:.3f} wall s; 0 GPU s. New run alone: {s['new_run_CPU_seconds']:.3f} CPU s.",fontsize=10.3,color='#444')
    for ext in('png','svg'):fig.savefig(PUBLIC/f'safety-capacity-tradeoff.{ext}',dpi=180,facecolor='white',metadata={'Date':None}if ext=='svg'else None)
    receipt=dict(input_sha256={str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest()for p in(path,Path(__file__))},output_sha256={f'safety-capacity-tradeoff.{ext}':hashlib.sha256((PUBLIC/f'safety-capacity-tradeoff.{ext}').read_bytes()).hexdigest()for ext in('png','svg')});(PUBLIC/'plot-provenance.json').write_text(json.dumps(receipt,indent=2)+'\n');print(receipt['output_sha256'])
if __name__=='__main__':main()
